if (!root) return false;

if (root->is_leaf()) {
    for (std::size_t i = 0; i < root->keys.size(); ++i) {
        if (root->keys[i] == key) return true;
    }
    return false;
}

std::size_t i = 0;
while (i < root->keys.size() && key > root->keys[i]) {
    ++i;
}

return search_key(root->children[i], key);
